/* Contents: highlight the section being read; on narrow screens the list
   starts collapsed and closes again after a jump. */
SATSTREET.mountHeader('Bitcoin Whitepaper');
(function () {
  var box = document.getElementById('wp-toc-box');
  var narrow = window.matchMedia('(max-width: 1023px)');
  function fit() { box.open = !narrow.matches; }
  fit();
  if (narrow.addEventListener) narrow.addEventListener('change', fit);
  var links = Array.prototype.slice.call(box.querySelectorAll('a'));
  links.forEach(function (a) { a.addEventListener('click', function () { if (narrow.matches) box.open = false; }); });
  var secs = links.map(function (a) { return document.getElementById(a.getAttribute('href').slice(1)); }).filter(Boolean);
  if (!('IntersectionObserver' in window)) return;
  var current = null;
  var io = new IntersectionObserver(function () {
    var best = null;
    secs.forEach(function (s) { if (s.getBoundingClientRect().top < window.innerHeight * 0.35) best = s; });
    if (best === current) return;
    current = best;
    links.forEach(function (a) { a.setAttribute('aria-current', best && a.getAttribute('href') === '#' + best.id ? 'true' : 'false'); });
  }, { rootMargin: '0px 0px -60% 0px', threshold: [0, 1] });
  secs.forEach(function (s) { io.observe(s); });
})();
